+        expect(
+          sink.events.map((e) => e.kind),
+          contains(AgentTelemetryEventKind.requestStart),
+        );
+        expect(
+          sink.events.map((e) => e.kind),
+          isNot(contains(AgentTelemetryEventKind.firstToken)),
+        );
