+      baseUrl: baseUrl,
+      envRead: envRead,
+      storeRead: storeRead,
+      activeCustomKeyName: activeCustomKeyName,
+    );
+    // The registry leg: a known pinned twin holding a value keeps winning
+    // while the chain landed on the canonical (or nothing) — the same
