/// Whether [url] matches a known provider whose SSO cookie can expire and
/// produce a redirect.
bool _isKnownAuthExpiredHost(String url) {
  final lower = url.toLowerCase();
  return lower.contains('codemie') || lower.contains('code-assistant-api');
}

